exercises.solution:
const form = document.querySelector('#profile');
const preview = document.querySelector('#preview');

const data = new FormData(form);
const parts = [];

for (const [key, value] of data) {
  parts.push(key + '=' + value);
}

preview.textContent = parts.join('; ');
